r"""build_do5_data.py — DAY ORDER 5 (2026-10-24): CM-KG\ESTATE\worker\do5-data.js, the market lines of the DAY ORDER 5 pages (do5.js), from the record:
  · the ECO hunt of record, the newest file per market (REFERENCE\ECO\hunt-2026-10-24 over hunt-2026-10-23): only fields in state "sourced", each with its source page;
  · eu.json (the EU regime object and its market rows) from hunt-2026-10-24;
  · residency of a live node from the door's environment and the store's region (RAILS\zones-do5\doors-2026-10-24.json, RAILS\eu-node\live.json, row-nodes.json).
Nothing typed: a market with no hunt file prints its country only. Usage: python -X utf8 -I build_do5_data.py"""
import os, json, re, glob
R = r'C:\ALLOOLOO\CM-KG'; HERE = os.path.dirname(os.path.abspath(__file__))
HUNTS = [os.path.join(R, 'REFERENCE', 'ECO', 'hunt-2026-10-24'), os.path.join(R, 'REFERENCE', 'ECO', 'hunt-2026-10-23')]
EU14 = 'it es se dk no fi be ie at pl pt lu gr cz'.split(); OWN = 'lu ky bm je in tw sa ae br mx'.split()
COUNTRY = {'it': 'Italy', 'es': 'Spain', 'se': 'Sweden', 'dk': 'Denmark', 'no': 'Norway', 'fi': 'Finland', 'be': 'Belgium', 'ie': 'Ireland', 'at': 'Austria', 'pl': 'Poland', 'pt': 'Portugal', 'lu': 'Luxembourg', 'gr': 'Greece', 'cz': 'Czech Republic',
           'ky': 'Cayman Islands', 'bm': 'Bermuda', 'je': 'Jersey', 'in': 'India', 'tw': 'Taiwan', 'sa': 'Saudi Arabia', 'ae': 'United Arab Emirates', 'br': 'Brazil', 'mx': 'Mexico'}
AZ = {'italynorth': 'Italy North (Milan)', 'spaincentral': 'Spain Central (Madrid)', 'swedencentral': 'Sweden Central (Gävle)', 'norwayeast': 'Norway East (Oslo)', 'westeurope': 'West Europe (Amsterdam)', 'germanywestcentral': 'Germany West Central (Frankfurt)',
      'belgiumcentral': 'Belgium Central (Brussels)', 'northeurope': 'North Europe (Dublin)', 'austriaeast': 'Austria East (Vienna)', 'polandcentral': 'Poland Central (Warsaw)', 'eastus': 'East US (Virginia)', 'uksouth': 'UK South (London)',
      'southeastasia': 'Southeast Asia (Singapore)', 'eastasia': 'East Asia (Hong Kong)', 'centralindia': 'Central India (Pune)', 'uaenorth': 'UAE North (Dubai)', 'brazilsouth': 'Brazil South (São Paulo)', 'mexicocentral': 'Mexico Central (Querétaro)'}
KEEP = ['regulator', 'exchanges', 'regulated_information_store', 'periodic_disclosure', 'ad_hoc_regime', 'filing_format', 'filing_languages', 'isin_prefix', 'trading_halts_page', 'store_lookup_url']
def hunt(cc):
    for h in HUNTS:
        p = os.path.join(h, cc + '.json')
        if os.path.exists(p): return json.load(open(p, encoding='utf-8')), os.path.basename(h)
    return None, None
store_region = json.load(open(os.path.join(R, 'RAILS', 'eu-node', 'live.json'), encoding='utf-8'))
doors = json.load(open(os.path.join(HERE, 'doors-2026-10-24.json'), encoding='utf-8'))
rowp = os.path.join(HERE, 'row-nodes.json'); row = json.load(open(rowp, encoding='utf-8')) if os.path.exists(rowp) else {}
M = {}
for cc in sorted(set(EU14 + OWN)):
    h, hn = hunt(cc); f = (h or {}).get('fields', {})
    eco = {k: {kk: f[k].get(kk) for kk in ('value', 'url', 'source')} for k in KEEP if k in f and f[k].get('state') == 'sourced'}
    reg = (eco.get('regulator') or {}).get('value') or ''
    m = re.search(r'\(([^()]{2,12})\)\s*$', str(reg)); short = m.group(1) if m else (str(reg).split(' (')[0][:60] or None)
    st = (eco.get('regulated_information_store') or {}).get('value')
    sr, dr = None, None
    if cc in doors: sr, dr = store_region.get(cc), doors[cc]['env'].replace('cmkg-env-', '').split('-')[0]
    if cc in row: sr, dr = row[cc].get('store_region'), row[cc].get('door_region')
    res = None
    if sr and dr: res = f"Store of record: Azure {AZ.get(sr, sr)}." + (f" Door: Azure {AZ.get(dr, dr)} (nearest environment)." if dr != sr else ' Door: the same region.')
    M[cc] = {'country': COUNTRY[cc], 'eu': cc in EU14, 'eco': eco, 'regulator_short': short, 'store_named': (str(st).split(';')[0][:140] if st else None), 'residency': res, 'hunt': hn}
eu, _ = hunt('eu'); eu = eu or {}
rows = [{'cc': r.get('cc'), 'country': r.get('country'), 'nca': (r.get('nca') or {}).get('name') if isinstance(r.get('nca'), dict) else r.get('nca'), 'nca_url': (r.get('nca') or {}).get('url') if isinstance(r.get('nca'), dict) else r.get('nca_url'), 'eco_page': r.get('eco_page')} for r in (eu.get('markets') or (eu.get('fields', {}).get('markets', {}) or {}).get('value') or [])]
regime = {'fields': {k: {kk: v.get(kk) for kk in ('value', 'url', 'source')} for k, v in (eu.get('fields') or {}).items() if isinstance(v, dict) and v.get('state') == 'sourced' and k != 'markets'}}
out = os.path.join(R, 'ESTATE', 'worker', 'do5-data.js')
js = ('// do5-data.js — generated by CM-KG\\RAILS\\zones-do5\\build_do5_data.py (DAY ORDER 5, 2026-10-24) from the ECO hunt of record. Do not edit by hand.\n'
      f"export const VERSION5 = '2026-10-24.5';\nexport const M = {json.dumps(M, ensure_ascii=False)};\nexport const EU_REGIME = {json.dumps(regime, ensure_ascii=False)};\nexport const EU_ROWS = {json.dumps(rows, ensure_ascii=False)};\n")
open(out, 'w', encoding='utf-8').write(js)
print('do5-data.js', len(M), 'markets ·', sum(1 for v in M.values() if v['eco']), 'with ECO fields ·', len(rows), 'EU rows ·', len(regime['fields']), 'regime fields')
